import {readFileSync} from 'node:fs';
import {resolve} from 'node:path';
import {fileURLToPath} from 'node:url';

function isNonNegSafeInt(x){return Number.isSafeInteger(x)&&x>=0;}
function isPosSafeInt(x){return Number.isSafeInteger(x)&&x>=1;}

export function nextRetry(o){
  if(typeof o!=='object'||o===null||Array.isArray(o))
    throw new Error('options must be a non-null, non-array object');
  if(!isPosSafeInt(o.attempt))
    throw new Error('attempt must be a positive safe integer');
  if(!isNonNegSafeInt(o.elapsedMs))
    throw new Error('elapsedMs must be a nonnegative safe integer');
  if(!isNonNegSafeInt(o.baseMs))
    throw new Error('baseMs must be a nonnegative safe integer');
  if(!isNonNegSafeInt(o.maxDelayMs))
    throw new Error('maxDelayMs must be a nonnegative safe integer');
  if(!isNonNegSafeInt(o.budgetMs))
    throw new Error('budgetMs must be a nonnegative safe integer');
  if(!(o.retryAfterMs===null||isNonNegSafeInt(o.retryAfterMs)))
    throw new Error('retryAfterMs must be null or a nonnegative safe integer');
  if(typeof o.retryable!=='boolean')
    throw new Error('retryable must be a boolean');

  if(!o.retryable)
    return {retry:false,delayMs:null,reason:'non-retryable'};

  const expDelay=o.baseMs===0?0:Math.min(o.baseMs*2**(o.attempt-1),o.maxDelayMs);
  const wait=o.retryAfterMs!==null?Math.max(expDelay,o.retryAfterMs):expDelay;

  if(o.elapsedMs>o.budgetMs||wait>o.budgetMs-o.elapsedMs)
    return {retry:false,delayMs:null,reason:'budget-exhausted'};

  return {retry:true,delayMs:wait,reason:'scheduled'};
}

function isCliMain(){
  return process.argv.length>1&&resolve(process.argv[1])===fileURLToPath(import.meta.url);
}

if(isCliMain()){
  try{
    const args=process.argv.slice(2);
    if(args.length!==1)
      throw new Error('usage: node retry-budget.js INPUT_JSON_FILE');
    const options=JSON.parse(readFileSync(args[0],'utf8'));
    process.stdout.write(JSON.stringify(nextRetry(options))+'\n');
  }catch(err){
    process.stderr.write(String(err&&err.message?err.message:err)+'\n');
    process.exitCode=2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {mkdtempSync,writeFileSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const __dirname=dirname(fileURLToPath(import.meta.url));
const ROOT=join(__dirname,'..');
const CLI=join(ROOT,'retry-budget.js');

const base={attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true};

test('exponential growth with cap',()=>{
  assert.deepEqual(nextRetry({...base,attempt:1}),{retry:true,delayMs:10,reason:'scheduled'});
  assert.deepEqual(nextRetry({...base,attempt:2}),{retry:true,delayMs:20,reason:'scheduled'});
  assert.deepEqual(nextRetry({...base,attempt:4}),{retry:true,delayMs:80,reason:'scheduled'});
  assert.deepEqual(nextRetry({...base,attempt:5}),{retry:true,delayMs:100,reason:'scheduled'});
  assert.deepEqual(nextRetry({...base,attempt:9}),{retry:true,delayMs:100,reason:'scheduled'});
});

test('huge attempt without overflow (capped)',()=>{
  assert.deepEqual(nextRetry({...base,attempt:Number.MAX_SAFE_INTEGER}),{retry:true,delayMs:100,reason:'scheduled'});
});

test('zero base means zero delay even for huge attempt',()=>{
  assert.deepEqual(nextRetry({...base,baseMs:0,attempt:Number.MAX_SAFE_INTEGER}),{retry:true,delayMs:0,reason:'scheduled'});
});

test('retryAfterMs is a floor, not capped by maxDelayMs',()=>{
  assert.deepEqual(nextRetry({...base,baseMs:0,retryAfterMs:5000}),{retry:true,delayMs:5000,reason:'scheduled'});
  assert.deepEqual(nextRetry({...base,retryAfterMs:5000}),{retry:true,delayMs:5000,reason:'scheduled'});
});

test('retryAfterMs does not shrink the exponential delay',()=>{
  assert.deepEqual(nextRetry({...base,attempt:5,retryAfterMs:10}),{retry:true,delayMs:100,reason:'scheduled'});
});

test('equality at the budget boundary is allowed',()=>{
  assert.deepEqual(nextRetry({...base,elapsedMs:990}),{retry:true,delayMs:10,reason:'scheduled'});
});

test('one ms over the budget boundary is exhausted',()=>{
  assert.deepEqual(nextRetry({...base,elapsedMs:991}),{retry:false,delayMs:null,reason:'budget-exhausted'});
});

test('elapsed already over budget is exhausted',()=>{
  assert.deepEqual(nextRetry({...base,elapsedMs:2000}),{retry:false,delayMs:null,reason:'budget-exhausted'});
});

test('retryAfterMs can push past the budget',()=>{
  assert.deepEqual(nextRetry({...base,elapsedMs:0,retryAfterMs:1001}),{retry:false,delayMs:null,reason:'budget-exhausted'});
  assert.deepEqual(nextRetry({...base,elapsedMs:0,retryAfterMs:1000}),{retry:true,delayMs:1000,reason:'scheduled'});
});

test('validation throws on invalid input',()=>{
  const mustThrow=(v)=>assert.throws(()=>nextRetry(v),Error);
  mustThrow(null);
  mustThrow(undefined);
  mustThrow(42);
  mustThrow('nope');
  mustThrow(true);
  mustThrow([1,2,3]);
  mustThrow({...base,attempt:0});
  mustThrow({...base,attempt:-1});
  mustThrow({...base,attempt:1.5});
  mustThrow({...base,attempt:NaN});
  mustThrow({...base,attempt:Number.MAX_SAFE_INTEGER+2});
  mustThrow({...base,elapsedMs:-1});
  mustThrow({...base,baseMs:-1});
  mustThrow({...base,maxDelayMs:-1});
  mustThrow({...base,budgetMs:-1});
  mustThrow({...base,retryAfterMs:-1});
  mustThrow({...base,retryAfterMs:'soon'});
  mustThrow({...base,retryable:'true'});
  mustThrow({...base,retryable:1});
  mustThrow({...base,attempt:undefined});
  mustThrow({...base,retryable:undefined});
});

test('validates every field even when retryable is false',()=>{
  assert.throws(()=>nextRetry({...base,retryable:false,attempt:0}),Error);
  assert.throws(()=>nextRetry({...base,retryable:false,baseMs:'10'}),Error);
});

test('extra fields are ignored',()=>{
  assert.deepEqual(nextRetry({...base,junk:'x',arr:[1]}),{retry:true,delayMs:10,reason:'scheduled'});
});

test('does not mutate input and frozen objects work',()=>{
  const frozen=Object.freeze({...base});
  assert.deepEqual(nextRetry(frozen),{retry:true,delayMs:10,reason:'scheduled'});
  assert.deepEqual(frozen,base);
});

test('CLI: success prints one JSON value, exit 0, no stderr',()=>{
  const dir=mkdtempSync(join(tmpdir(),'rb-'));
  try{
    const file=join(dir,'in.json');
    writeFileSync(file,JSON.stringify(base));
    const out=execFileSync(process.execPath,[CLI,file],{encoding:'utf8',stdio:['ignore','pipe','pipe']});
    assert.equal(out,JSON.stringify({retry:true,delayMs:10,reason:'scheduled'})+'\n');
    assert.equal(JSON.parse(out).retry,true);
  }finally{rmSync(dir,{recursive:true,force:true});}
});

test('CLI: a non-retry decision is still success',()=>{
  const dir=mkdtempSync(join(tmpdir(),'rb-'));
  try{
    const file=join(dir,'in.json');
    writeFileSync(file,JSON.stringify({...base,retryable:false}));
    const out=execFileSync(process.execPath,[CLI,file],{encoding:'utf8'});
    assert.equal(out,JSON.stringify({retry:false,delayMs:null,reason:'non-retryable'})+'\n');
  }finally{rmSync(dir,{recursive:true,force:true});}
});

test('CLI: invalid cases exit 2 with nonempty stderr and no stdout',()=>{
  const dir=mkdtempSync(join(tmpdir(),'rb-'));
  const run=(args)=>{
    let stdout='',stderr='',code=0;
    try{
      stdout=execFileSync(process.execPath,[CLI,...args],{encoding:'utf8',stdio:['ignore','pipe','pipe']});
    }catch(e){stdout=e.stdout??'';stderr=e.stderr??'';code=e.status??1;}
    return{stdout,stderr,code};
  };
  const badFile=join(dir,'bad.json');
  writeFileSync(badFile,'{not json');
  const empty=join(dir,'empty.json');
  writeFileSync(empty,'null');
  const cases=[
    [],
    [join(dir,'missing.json')],
    [badFile],
    [empty],
    [join(dir,'a.json'),join(dir,'b.json')],
  ];
  for(const args of cases){
    const r=run(args);
    assert.equal(r.code,2,'stderr nonempty and exit 2 for '+JSON.stringify(args));
    assert.ok(r.stderr.length>0);
    assert.equal(r.stdout,'');
  }
  rmSync(dir,{recursive:true,force:true});
});

test('CLI: API input error (bad object) exits 2',()=>{
  const dir=mkdtempSync(join(tmpdir(),'rb-'));
  try{
    const file=join(dir,'in.json');
    writeFileSync(file,JSON.stringify({...base,attempt:0}));
    let code=0,stderr='';
    try{execFileSync(process.execPath,[CLI,file],{stdio:['ignore','pipe','pipe']});}
    catch(e){stderr=e.stderr??'';code=e.status??1;}
    assert.equal(code,2);
    assert.ok(stderr.length>0);
  }finally{rmSync(dir,{recursive:true,force:true});}
});

