import {nextRetry} from "/workspace/retry-budget.js";
const b={attempt:1,elapsedMs:0,baseMs:10,maxDelayMs:100,budgetMs:1000,retryAfterMs:null,retryable:true};
const show=(o)=>JSON.stringify(nextRetry(o));
// overflow / huge attempt, nonzero base
console.log("huge attempt:", show({...b,attempt:Number.MAX_SAFE_INTEGER}));
// zero base huge attempt
console.log("zero base huge:", show({...b,baseMs:0,attempt:Number.MAX_SAFE_INTEGER}));
// exact cap boundary: baseMs*2^(a-1) === maxDelayMs
console.log("exact cap:", show({...b,baseMs:50,attempt:2})); // 50*2=100 == maxDelayMs
console.log("exact cap+1:", show({...b,baseMs:50,attempt:3})); // 50*4=200 -> capped 100
// budget equality
console.log("budget equal:", show({...b,attempt:5,elapsedMs:900})); // wait 100, 900+100=1000
console.log("budget over:", show({...b,attempt:5,elapsedMs:901}));
// elapsed exactly budget, zero wait
console.log("elapsed=budget zero wait:", show({...b,baseMs:0,elapsedMs:1000}));
// retryAfter huge not capped
console.log("hint not capped:", show({...b,baseMs:0,retryAfterMs:Number.MAX_SAFE_INTEGER,budgetMs:Number.MAX_SAFE_INTEGER}));
// huge attempt timing (no proportional loop) - measure
const t0=process.hrtime.bigint();
for(let i=0;i<1000;i++) nextRetry({...b,attempt:Number.MAX_SAFE_INTEGER});
const t1=process.hrtime.bigint();
console.log("1000 huge calls ms:", Number(t1-t0)/1e6);
'

